api_mappings.custom_func_imp:
nvjpegStatus_t nvjpegGetCudartProperty(libraryPropertyType type, int * value) {
    // TraceCall("nvjpegGetCudartProperty");
    if(type == MAJOR_VERSION) {
        *value = CUDART_VERSION / 1000;
    } else if (type == MINOR_VERSION) {
        *value = (CUDART_VERSION % 1000) / 10;
    } else if (type == PATCH_LEVEL) {
        *value = CUDART_VERSION % 10;
    } else {
        printf("Unknown library property type: %d\n", type);
        return NVJPEG_STATUS_JPEG_NOT_SUPPORTED;
    }
    return NVJPEG_STATUS_SUCCESS;
}

nvjpegStatus_t nvjpegGetProperty(libraryPropertyType type, int * value) {
    // TraceCall("nvjpegGetProperty");
    if(type == MAJOR_VERSION) {
        *value = NVJPEG_VER_MAJOR;
    } else if (type == MINOR_VERSION) {
        *value = NVJPEG_VER_MINOR;
    } else if (type == PATCH_LEVEL) {
        *value = NVJPEG_VER_PATCH;
    } else {
        printf("Unknown library property type: %d\n", type);
        return NVJPEG_STATUS_JPEG_NOT_SUPPORTED;
    }
    return NVJPEG_STATUS_SUCCESS;
}

global_custom_code.pre_wrapper_call:
bool needProfile = g_profileHandler.isCallbackEnabled != NULL &&
    g_profileHandler.isCallbackEnabled(g_profileDomain, nvjpeg_TRACE_CBID_$WRAPPER_FUNC_NAME) != 0;
if (needProfile) {
    g_profileHandler.profileCallbackBegin(g_profileDomain, nvjpeg_TRACE_CBID_$WRAPPER_FUNC_NAME);
}
